BEGINNING-OF-PROGRAM
    DEFINE-NEW-INSTRUCTION copy-up AS
    BEGIN
        turnleft;
        move;
        putbeeper;
        turnleft;
        turnleft;
        move;
        turnleft
    END
    BEGINNING-OF-EXECUTION
        WHILE front-is-clear DO
        BEGIN
            IF next-to-a-beeper THEN
                copy-up;
            move
        END
        IF next-to-a-beeper THEN
            copy-up;
        turnoff
    END-OF-EXECUTION
END-OF-PROGRAM
